mapper.select:
SELECT F.FLIGHT_NO, F.FLIGHT_STATUS, F.DEPARTURE_TIME, F.ARRIVAL_TIME, F.DELAY_MINUTES, DA.IATA_CODE AS DEP_IATA, DA.AIRPORT_NAME AS DEP_NAME, AA.IATA_CODE AS ARR_IATA, AA.AIRPORT_NAME AS ARR_NAME, DG.GATE_CODE AS DEP_GATE, AG.GATE_CODE AS ARR_GATE FROM FLIGHT F INNER JOIN ROUTE R ON F.ROUTE_ID = R.ROUTE_ID INNER JOIN AIRPORT DA ON R.DEPARTURE_AIRPORT_ID = DA.AIRPORT_ID INNER JOIN AIRPORT AA ON R.ARRIVAL_AIRPORT_ID = AA.AIRPORT_ID LEFT OUTER JOIN GATE DG ON F.DEPARTURE_GATE_ID = DG.GATE_ID LEFT OUTER JOIN GATE AG ON F.ARRIVAL_GATE_ID = AG.GATE_ID WHERE F.IS_DELETED = 'N'
AND TO_CHAR(F.DEPARTURE_TIME, 'YYYY-MM-DD') >= #{startDate}
AND TO_CHAR(F.DEPARTURE_TIME, 'YYYY-MM-DD') <= #{endDate}
AND R.DEPARTURE_AIRPORT_ID = #{departureId}
AND R.ARRIVAL_AIRPORT_ID = #{arrivalId}
AND UPPER(F.FLIGHT_NO) = UPPER(#{flightNo})
ORDER BY F.DEPARTURE_TIME ASC

SELECT F.FLIGHT_NO, F.DEPARTURE_TIME, F.ARRIVAL_TIME, DA.IATA_CODE AS DEP_IATA, DA.AIRPORT_NAME AS DEP_NAME, AA.IATA_CODE AS ARR_IATA, AA.AIRPORT_NAME AS ARR_NAME, AC.MODEL_NAME FROM FLIGHT F INNER JOIN ROUTE R ON F.ROUTE_ID = R.ROUTE_ID INNER JOIN AIRPORT DA ON R.DEPARTURE_AIRPORT_ID = DA.AIRPORT_ID INNER JOIN AIRPORT AA ON R.ARRIVAL_AIRPORT_ID = AA.AIRPORT_ID INNER JOIN AIRCRAFT AC ON F.AIRCRAFT_ID = AC.AIRCRAFT_ID WHERE F.IS_DELETED = 'N' AND R.DEPARTURE_AIRPORT_ID = #{departureId} AND R.ARRIVAL_AIRPORT_ID = #{arrivalId}
AND TO_CHAR(F.DEPARTURE_TIME, 'YYYY-MM-DD') >= #{startDate}
AND TO_CHAR(F.DEPARTURE_TIME, 'YYYY-MM-DD') <= #{endDate}
ORDER BY F.DEPARTURE_TIME ASC
